# region: shape
def shape(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: sift
def sift(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: emit
def emit(xs, offset=4):
    return [v + offset for v in xs]

# region: fold
def fold(xs, cut=5):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v >= cut]
    return {'n': len(xs), 'lo': len(lo), 'hi': len(hi)}

# region: gather
def gather(summary, bar=4):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) > bar else 'low'
    return out

# region: run
def run(raw):
    return gather(fold(emit(sift(shape(raw)))))

